254	// TestReserveFailedSubmissionRemainsReusable 验证尚未成功占用的编号继续按本次
255	// 参数、资格和库存判断，失败后允许用该编号再次提交，失败不固定成永久结果。
256	func TestReserveFailedSubmissionRemainsReusable(t *testing.T) {
257		s := newStore(t)
258		// 参数非法失败。
259		if _, err := s.Reserve("c1", "r1", "part1", 0, expiryOK, nowOK); !errors.Is(err, ErrInvalidParam) {
260			t.Fatalf("zero quantity: %v", err)
261		}
262		// 库存不足失败。
263		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrInsufficientStock) {
264			t.Fatalf("over stock: %v", err)
265		}
266		// 请求过保失败。
267		if _, err := s.Reserve("c1", "r1", "part1", 1, expiryOK, t0.Add(31*day)); !errors.Is(err, ErrIneligible) {
268			t.Fatalf("ineligible: %v", err)
269		}
270		// 条件满足后同编号首次成功。
271		first, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
272		if err != nil {
273			t.Fatalf("reserve after failures: %v", err)
274		}
275		if first.Quantity != 4 {
276			t.Fatalf("commitment = %+v", first)
277		}
278		st, _ := s.PartStatus("part1", nowOK)
279		if st.ActiveOccupied != 4 {
280			t.Fatalf("occupied = %d, want 4", st.ActiveOccupied)
281		}
282		// 成功之后，再用曾经失败过的参数提交即按冲突处理。
283		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrConflict) {
284			t.Fatalf("reused id after success: got %v, want ErrConflict", err)
285		}
286	}
287	
288	// TestReserveRetryConcurrentWithUseAndCancel 验证并发原样重试只能取回首次成功值，
289	// 且只产生一次占用和一条成功历史；查询反映实际完成的使用与取消。
290	func TestReserveRetryConcurrentWithUseAndCancel(t *testing.T) {
291		s := newStore(t)
292		first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
293		if err != nil {
294			t.Fatalf("reserve: %v", err)
295		}
296	
297		const retryN = 16
298		var wg sync.WaitGroup
299		var mu sync.Mutex
300		var badRetries int
301		useOK := 0
302		for i := 0; i < retryN; i++ {
303			wg.Add(1)
304			go func(i int) {
305				defer wg.Done()
306				got, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, expiryOK.Add(time.Duration(i)*time.Hour))
307				mu.Lock()
308				defer mu.Unlock()
309				if err != nil || got != first {
310					badRetries++
311				}
312			}(i)
313		}
314		for i := 0; i < 2; i++ {
315			wg.Add(1)
316			go func(i int) {
317				defer wg.Done()
318				_, err := s.Use(fmt.Sprintf("u%d", i), "c1", 1, nowOK)
319				mu.Lock()
320				defer mu.Unlock()
321				switch {
322				case err == nil:
323					useOK++
324				case errors.Is(err, ErrCommitmentClosed), errors.Is(err, ErrUsageExceeded):
325				default:
326					t.Errorf("unexpected use error: %v", err)
327				}
328			}(i)
329		}
330		wg.Add(1)
331		go func() {
332			defer wg.Done()
333			if _, err := s.Cancel("c1", nowOK); err != nil {
334				t.Errorf("cancel: %v", err)
335			}
336		}()
337		wg.Wait()
338	
339		if badRetries != 0 {
340			t.Fatalf("%d retries did not return the first result", badRetries)
341		}
342		// 只有一条成功历史，重试不追加。
343		h, _ := s.RequestHistory("r1")
344		if len(h) != 1 || !h[0].Success {
345			t.Fatalf("history = %+v, want single success", h)
346		}
347		// 查询反映实际完成的操作：取消后占用为零，实物只扣减成功使用量。
348		st, _ := s.PartStatus("part1", nowOK)
349		if st.ActiveOccupied != 0 || st.PhysicalRemaining != 10-useOK {
350			t.Fatalf("state after concurrent retry/use/cancel: used=%d status=%+v", useOK, st)
351		}
352		d := st.Details[0]
353		if d.Status != CommitmentCanceled || d.UsedQuantity != useOK {
354			t.Fatalf("detail = %+v, want canceled with used=%d", d, useOK)
355		}
356	}
