1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 本文件回归保障取消功能在同一备件被多笔承诺共同占用时的行为：取消一笔只
9	// 释放这笔承诺自身的未用数量，已使用的部分不回补实物库存，其他请求或同一
10	// 请求的其他有效承诺一律不受影响；释放出的可承诺数量随后可以被新的合格请求
11	// 全部预留，且对已取消承诺的重复取消与新使用都不能再次改变库存。
12	
13	// cancelSharedStore 构造一个保修 60 天的产品、初始库存 12 件的备件和三个
14	// 保修资格请求（请求甲 rA、请求乙 rB、取消后新到的请求 rC）。
15	func cancelSharedStore(t *testing.T) *Store {
16		t.Helper()
17		s := NewStore()
18		if err := s.RegisterProduct("p1", t0, 60, nil); err != nil {
19			t.Fatalf("register product: %v", err)
20		}
21		if err := s.RegisterPart("part1", 12); err != nil {
22			t.Fatalf("register part: %v", err)
23		}
24		for _, id := range []string{"rA", "rB", "rC"} {
25			if err := s.SubmitRequest(id, "p1", "FAULTY"); err != nil {
26				t.Fatalf("submit request %s: %v", id, err)
27			}
28		}
29		return s
30	}
31	
32	// mustDetailByID 在承诺明细列表中按编号查找，找不到时失败。
33	func mustDetailByID(t *testing.T, details []CommitmentDetail, commitID string) CommitmentDetail {
34		t.Helper()
35		for _, d := range details {
36			if d.CommitmentID == commitID {
37				return d
38			}
39		}
40		t.Fatalf("commitment %q not found in details %+v", commitID, details)
41		return CommitmentDetail{}
42	}
43	
44	// assertPartAccount 断言备件账目三项数值与调用方可见的库存规则一致：
45	// 实物剩余只扣成功使用量，有效占用只计有效承诺的未用数量。
46	func assertPartAccount(t *testing.T, s *Store, physical, occupied, committable int) {
47		t.Helper()
48		st, err := s.PartStatus("part1", nowOK)
49		if err != nil {
50			t.Fatalf("part status: %v", err)
51		}
52		if st.PhysicalRemaining != physical || st.ActiveOccupied != occupied || st.Committable != committable {
53			t.Fatalf("stock account: phys=%d occupied=%d committable=%d, want phys=%d occupied=%d committable=%d",
54				st.PhysicalRemaining, st.ActiveOccupied, st.Committable, physical, occupied, committable)
55		}
56	}
57	
58	// TestCancelReleasesOnlyThisCommitmentUnused 以同一备件初始库存 12 件为例：
59	// 请求甲两笔承诺分别预留 5 件和 2 件，请求乙一笔承诺预留 4 件。从甲的 5 件
60	// 承诺使用 2 件后取消该承诺，只能释放其未用的 3 件；取消记录仍可追查但不再
61	// 计入有效占用，甲的另一笔承诺与乙的承诺数量、归属和到期时刻保持原值。
62	func TestCancelReleasesOnlyThisCommitmentUnused(t *testing.T) {
63		s := cancelSharedStore(t)
64	
65		// 三笔承诺各给不同的到期时刻（均晚于全部操作时刻），以便回归保障取消
66		// 不会篡改其他承诺的到期时刻。
67		expA5 := t0.Add(40 * day)
68		expA2 := t0.Add(50 * day)
69		expB4 := t0.Add(30 * day)
70	
71		if _, err := s.Reserve("cA5", "rA", "part1", 5, expA5, nowOK); err != nil {
72			t.Fatalf("reserve cA5: %v", err)
73		}
74		if _, err := s.Reserve("cA2", "rA", "part1", 2, expA2, nowOK); err != nil {
75			t.Fatalf("reserve cA2: %v", err)
76		}
77		if _, err := s.Reserve("cB4", "rB", "part1", 4, expB4, nowOK); err != nil {
78			t.Fatalf("reserve cB4: %v", err)
79		}
80	
81		// 从请求甲的 5 件承诺中使用 2 件：实物 10，有效占用 9（3+2+4），可承诺 1。
82		if _, err := s.Use("uA-used", "cA5", 2, nowOK); err != nil {
83			t.Fatalf("use 2 from cA5: %v", err)
84		}
85		assertPartAccount(t, s, 10, 9, 1)
86	
87		// 取消这笔 5 件承诺：返回结果仍保留原定 5、已用 2、未用 3，并显示已取消。
88		canceled, err := s.Cancel("cA5", nowOK)
89		if err != nil {
90			t.Fatalf("cancel cA5: %v", err)
91		}
92		if !canceled.Canceled || canceled.Quantity != 5 || canceled.Used != 2 || canceled.Unused() != 3 {
93			t.Fatalf("cancel result: %+v, want qty=5 used=2 unused=3 canceled=true", canceled)
94		}
95	
96		// 实物仍是 10（已用 2 件不回补），有效占用降为 6（2+4），可承诺变为 4。
97		assertPartAccount(t, s, 10, 6, 4)
98	
99		// 直接取回的承诺同样保留原定/已用/未用事实并显示已取消。
100		got, err := s.Commitment("cA5")
101		if err != nil {
102			t.Fatalf("commitment cA5: %v", err)
103		}
104		if !got.Canceled || got.Quantity != 5 || got.Used != 2 || got.Unused() != 3 {
105			t.Fatalf("stored canceled commitment: %+v", got)
106		}
107	
108		// 按请求查看：请求甲仍能看到自己的两笔承诺。
109		viewA, err := s.RequestView("rA", nowOK)
110		if err != nil {
111			t.Fatalf("request view rA: %v", err)
112		}
113		if len(viewA.Commitments) != 2 {
114			t.Fatalf("rA commitments = %d, want 2 (canceled record still visible)", len(viewA.Commitments))
115		}
116		dA5 := mustDetailByID(t, viewA.Commitments, "cA5")
117		if dA5.Status != CommitmentCanceled || dA5.OriginalQuantity != 5 ||
118			dA5.UsedQuantity != 2 || dA5.RemainingQuantity != 3 ||
119			dA5.RequestID != "rA" || dA5.PartID != "part1" || !dA5.Expiry.Equal(expA5) {
120			t.Fatalf("rA view of cA5: %+v", dA5)
121		}
122		// 甲的另一笔承诺继续有效，数量、归属与到期时刻保持原值。
123		dA2 := mustDetailByID(t, viewA.Commitments, "cA2")
124		if dA2.Status != CommitmentActive || dA2.OriginalQuantity != 2 ||
125			dA2.UsedQuantity != 0 || dA2.RemainingQuantity != 2 ||
126			dA2.RequestID != "rA" || !dA2.Expiry.Equal(expA2) {
127			t.Fatalf("rA view of cA2 changed after cancel: %+v", dA2)
128		}
129	
130		// 请求乙只看到自己的承诺：4 件有效，原值不变。
131		viewB, err := s.RequestView("rB", nowOK)
132		if err != nil {
133			t.Fatalf("request view rB: %v", err)
134		}
135		if len(viewB.Commitments) != 1 {
136			t.Fatalf("rB commitments = %d, want 1", len(viewB.Commitments))
137		}
138		dB4 := mustDetailByID(t, viewB.Commitments, "cB4")
139		if dB4.Status != CommitmentActive || dB4.OriginalQuantity != 4 ||
140			dB4.UsedQuantity != 0 || dB4.RemainingQuantity != 4 ||
141			dB4.RequestID != "rB" || dB4.PartID != "part1" || !dB4.Expiry.Equal(expB4) {
142			t.Fatalf("rB view of cB4 changed after other request's cancel: %+v", dB4)
143		}
144	
145		// 按备件查看：取消记录仍保留在明细中，各笔状态与库存总数一致。
146		st, err := s.PartStatus("part1", nowOK)
147		if err != nil {
148			t.Fatalf("part status: %v", err)
149		}
150		if len(st.Details) != 3 {
151			t.Fatalf("part details = %d, want 3 (canceled record retained)", len(st.Details))
152		}
153		pdA5 := mustDetailByID(t, st.Details, "cA5")
154		if pdA5.Status != CommitmentCanceled || pdA5.OriginalQuantity != 5 ||
155			pdA5.UsedQuantity != 2 || pdA5.RemainingQuantity != 3 {
156			t.Fatalf("part detail cA5: %+v", pdA5)
157		}
158		if mustDetailByID(t, st.Details, "cA2").Status != CommitmentActive {
159			t.Fatal("part detail cA2 not active")
160		}
161		if mustDetailByID(t, st.Details, "cB4").Status != CommitmentActive {
162			t.Fatal("part detail cB4 not active")
163		}
164		// 明细中有效承诺的未用数量之和必须等于有效占用，已取消明细不参与。
165		activeUnused := 0
166		for _, d := range st.Details {
167			if d.Status == CommitmentActive {
168				activeUnused += d.RemainingQuantity
169			}
170		}
171		if activeUnused != st.ActiveOccupied {
172			t.Fatalf("active details unused sum = %d, want ActiveOccupied %d", activeUnused, st.ActiveOccupied)
173		}
174	}
175	
176	// TestCanceledUnusedCanBeReservedThenCancelStaysInert 取消释放出的 4 件可
177	// 承诺数量随后被一个有保修资格的新请求全部预留；此后再次取消原承诺不能二次
178	// 释放，原承诺上的新使用返回 ErrCommitmentClosed，其他请求已取得的占用不受
179	// 影响。
180	func TestCanceledUnusedCanBeReservedThenCancelStaysInert(t *testing.T) {
181		s := cancelSharedStore(t)
182	
183		if _, err := s.Reserve("cA5", "rA", "part1", 5, t0.Add(40*day), nowOK); err != nil {
184			t.Fatalf("reserve cA5: %v", err)
185		}
